        // Setup: Get tokens and prepare for exploit
        vm.startPrank(attacker);

        // Get BNB for buying tokens and gas
        deal(attacker, 100 ether);

        // Initialize interfaces
        token = IERC20(TARGET);
        router = IUniswapV2Router02(ROUTER);
        weth = router.WETH();

        vm.stopPrank();
    }

