    function testExploit() public {
        // Start exploit
        vm.startPrank(attacker);

        // Record initial balance for oracle check
        uint256 initialBalance = attacker.balance;

        // Initialize interfaces
        token = IERC20(TARGET);
        router = IUniswapV2Router02(ROUTER);
        weth = router.WETH();

        console.log("Initial attacker balance:", initialBalance);

        // First, let's examine the contract more carefully
        // The contract might have ETH from previous swaps
        uint256 contractEthBalance = TARGET.balance;
        console.log("Contract ETH balance:", contractEthBalance);

        // If contract has ETH, maybe we can extract it somehow
        // Check if there are any functions that send ETH
        // The contract has no withdraw function except swapAndLiquify

        // Actually, wait! Look at the swapTokensForEth function:
        // It calls router.swapExactTokensForETHSupportingFeeOnTransferTokens
        // with path[1] = WETH, and to = address(this)
        // So ETH goes to contract, not to us

